@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --red: #E63946;
  --red-dark: #c1121f;
  --red-bright: #FF0000;
  --bg: #111111;
  --bg-card: #1a1a1a;
  --bg-elevated: #222222;
  --text: #ffffff;
  --text-muted: #aaaaaa;
  --text-subtle: #666666;
  --border: #2a2a2a;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --radius: 4px;
  --transition: 0.25s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ── PROMO BAR ─────────────────────────────────────────────── */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 20px;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.03em;
}
.promo-bar a {
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: 8px;
  opacity: 0.9;
  transition: opacity var(--transition);
}
.promo-bar a:hover { opacity: 1; }

/* ── NAVIGATION ────────────────────────────────────────────── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  padding: 0 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  transition: color var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--text); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-btn {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 9px 18px;
  border-radius: var(--radius);
  transition: all var(--transition);
}
.nav-btn-primary {
  background: var(--red);
  color: #fff;
}
.nav-btn-primary:hover { background: var(--red-dark); }
.nav-btn-ghost {
  color: var(--text-muted);
  border: 1px solid var(--border);
}
.nav-btn-ghost:hover { color: var(--text); border-color: #444; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 6px;
  cursor: pointer;
}
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text);
  transition: all var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 200;
  flex-direction: column;
  padding: 80px 32px 40px;
  gap: 24px;
}
.mobile-menu.open { display: flex; }
.mobile-menu a {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text);
  border-bottom: 1px solid var(--border);
  padding-bottom: 16px;
}
.mobile-menu-close {
  position: absolute;
  top: 20px;
  right: 24px;
  font-size: 28px;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  line-height: 1;
}

/* ── BUTTONS ───────────────────────────────────────────────── */
.btn {
  display: inline-block;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 15px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 36px;
  border-radius: var(--radius);
  transition: all 0.2s ease;
  cursor: pointer;
}
.btn-primary {
  background: var(--red);
  color: #fff;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
}
.btn-outline {
  background: transparent;
  color: #fff;
  border: 2px solid #fff;
}
.btn-outline:hover {
  background: #fff;
  color: #111;
}
.btn-dark {
  background: #111;
  color: #fff;
  border: 2px solid var(--red);
}
.btn-dark:hover {
  background: var(--red);
}
.btn-lg {
  font-size: 16px;
  padding: 18px 48px;
}

/* ── SECTION HEADINGS ──────────────────────────────────────── */
.section-label {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 12px;
