  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 0.04em;
}
h1 { font-size: clamp(42px, 7vw, 88px); font-weight: 700; }
h2 { font-size: clamp(32px, 5vw, 56px); font-weight: 700; }
h3 { font-size: clamp(20px, 3vw, 28px); font-weight: 600; }

/* ── LAYOUT HELPERS ────────────────────────────────────────── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 40px;
}
.container-wide {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 40px;
}
.section { padding: 100px 0; }
.section-sm { padding: 60px 0; }

/* ── HERO ──────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 90vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background-image: url('https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=1800&q=80');
  background-size: cover;
  background-position: center;
  filter: brightness(0.25) saturate(0.8);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(230,57,70,0.15) 0%, transparent 50%),
              linear-gradient(to top, rgba(17,17,17,0.9) 0%, transparent 60%);
}
.hero-content {
  position: relative;
  z-index: 2;
  padding: 60px 0;
}
.hero-eyebrow {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 40px;
  height: 2px;
  background: var(--red);
}
.hero-title {
  max-width: 800px;
  margin-bottom: 24px;
  text-shadow: 0 2px 40px rgba(0,0,0,0.8);
}
.hero-subtitle {
  font-size: 16px;
  color: var(--text-muted);
  max-width: 500px;
  margin-bottom: 40px;
  line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* ── COMMUNITY PROMO ───────────────────────────────────────── */
.community-promo {
  background: var(--bg-card);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.community-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.community-image {
  position: relative;
  height: 480px;
  border-radius: 2px;
  overflow: hidden;
}
.community-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.8) saturate(0.9);
}
.community-image::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 2px solid var(--red);
  border-radius: 2px;
  opacity: 0.4;
}
.community-text h2 { margin-bottom: 20px; }
.community-text p {
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1.8;
  margin-bottom: 32px;
}

/* ── TWO WAYS ──────────────────────────────────────────────── */
.two-ways { background: var(--bg); }
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 60px;
  border: 1px solid var(--border);
}
.way-card {
  background: var(--bg-card);
  padding: 60px 50px;
  position: relative;
  overflow: hidden;
  transition: all var(--transition);
}
.way-card:hover { background: var(--bg-elevated); }
.way-card::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform 0.3s ease;
}
.way-card:hover::before { transform: scaleX(1); }
.way-icon {
  width: 56px;
  height: 56px;
  background: rgba(230, 57, 70, 0.15);
  border: 1px solid rgba(230, 57, 70, 0.3);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 28px;
  color: var(--red);
  font-size: 22px;
}
.way-card h3 { margin-bottom: 16px; color: var(--text); }
.way-card p { color: var(--text-muted); line-height: 1.8; margin-bottom: 28px; font-size: 15px; }

/* ── STUDIO EXPERIENCE ─────────────────────────────────────── */
.studio-exp {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
}
.studio-exp-bg {
  position: absolute;
  inset: 0;
  background-image: url('https://images.unsplash.com/photo-1571902943202-507ec2618e8f?w=1800&q=80');
  background-size: cover;
  background-position: center;
  filter: brightness(0.2) saturate(0.6);
}
.studio-exp-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(17,17,17,0.95) 0%, rgba(17,17,17,0.6) 60%, transparent 100%);
}
.studio-exp-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}
.studio-exp-content h2 { margin-bottom: 20px; }
.studio-exp-content p {
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1.8;
  margin-bottom: 32px;
}
.studio-exp-content .book-cta {
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  font-weight: 700;
  margin-bottom: 20px;
}

/* ── FREE TRIAL CTA ────────────────────────────────────────── */
.free-trial {
  background: var(--red);
  padding: 100px 0;
  text-align: center;
}
.free-trial h2 {
  font-size: clamp(36px, 6vw, 72px);
  margin-bottom: 32px;
  text-shadow: 0 2px 20px rgba(0,0,0,0.3);
}
.free-trial .btn-outline { border-color: #fff; }

/* ── LIFESTYLE CAROUSEL ────────────────────────────────────── */
.carousel { background: var(--bg); overflow: hidden; }
.carousel-inner {
  position: relative;
  height: 520px;
}
.carousel-track {
  display: flex;
  height: 100%;
  transition: transform 0.55s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
