/* RedRoom Fitness — Shared Stylesheet */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --red: #E63946;
  --red-dark: #c1121f;
  --red-bright: #FF0000;
  --bg: #111111;
  --bg-card: #1a1a1a;
  --bg-elevated: #222222;
  --text: #ffffff;
  --text-muted: #aaaaaa;
  --text-subtle: #666666;
  --border: #2a2a2a;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --radius: 4px;
  --transition: 0.25s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ── PROMO BAR ─────────────────────────────────────────────── */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 20px;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.03em;
}
.promo-bar a {
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: 8px;
  opacity: 0.9;
  transition: opacity var(--transition);
}
.promo-bar a:hover { opacity: 1; }

/* ── NAVIGATION ────────────────────────────────────────────── */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  padding: 0 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}
.nav-links a {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  transition: color var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--text); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-btn {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 9px 18px;
  border-radius: var(--radius);
  transition: all var(--transition);
}
.nav-btn-primary {
  background: var(--red);
  color: #fff;
}
.nav-btn-primary:hover { background: var(--red-dark); }
.nav-btn-ghost {
  color: var(--text-muted);
  border: 1px solid var(--border);
}
.nav-btn-ghost:hover { color: var(--text); border-color: #444; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 6px;
  cursor: pointer;
}
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text);
  transition: all var(--transition);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 200;
  flex-direction: column;
  padding: 80px 32px 40px;
  gap: 24px;
}
.mobile-menu.open { display: flex; }
.mobile-menu a {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text);
  border-bottom: 1px solid var(--border);
  padding-bottom: 16px;
}
.mobile-menu-close {
  position: absolute;
  top: 20px;
  right: 24px;
  font-size: 28px;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  line-height: 1;
}

/* ── BUTTONS ───────────────────────────────────────────────── */
.btn {
  display: inline-block;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 15px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 14px 36px;
  border-radius: var(--radius);
  transition: all 0.2s ease;
  cursor: pointer;
}
.btn-primary {
  background: var(--red);
  color: #fff;
}
.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
}
.btn-outline {
  background: transparent;
  color: #fff;
  border: 2px solid #fff;
}
.btn-outline:hover {
  background: #fff;
  color: #111;
}
.btn-dark {
  background: #111;
  color: #fff;
  border: 2px solid var(--red);
}
.btn-dark:hover {
  background: var(--red);
}
.btn-lg {
  font-size: 16px;
  padding: 18px 48px;
}

/* ── SECTION HEADINGS ──────────────────────────────────────── */
.section-label {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 12px;
}
h1, h2, h3 {
  font-family: var(--font-display);
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 0.04em;
}
h1 { font-size: clamp(42px, 7vw, 88px); font-weight: 700; }
h2 { font-size: clamp(32px, 5vw, 56px); font-weight: 700; }
h3 { font-size: clamp(20px, 3vw, 28px); font-weight: 600; }

/* ── LAYOUT HELPERS ────────────────────────────────────────── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 40px;
}
.container-wide {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 40px;
}
.section { padding: 100px 0; }
.section-sm { padding: 60px 0; }

/* ── HERO ──────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 90vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background-image: url('https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=1800&q=80');
  background-size: cover;
  background-position: center;
  filter: brightness(0.25) saturate(0.8);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(230,57,70,0.15) 0%, transparent 50%),
              linear-gradient(to top, rgba(17,17,17,0.9) 0%, transparent 60%);
}
.hero-content {
  position: relative;
  z-index: 2;
  padding: 60px 0;
}
.hero-eyebrow {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 40px;
  height: 2px;
  background: var(--red);
}
.hero-title {
  max-width: 800px;
  margin-bottom: 24px;
  text-shadow: 0 2px 40px rgba(0,0,0,0.8);
}
.hero-subtitle {
  font-size: 16px;
  color: var(--text-muted);
  max-width: 500px;
  margin-bottom: 40px;
  line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* ── COMMUNITY PROMO ───────────────────────────────────────── */
.community-promo {
  background: var(--bg-card);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.community-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.community-image {
  position: relative;
  height: 480px;
  border-radius: 2px;
  overflow: hidden;
}
.community-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.8) saturate(0.9);
}
.community-image::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 2px solid var(--red);
  border-radius: 2px;
  opacity: 0.4;
}
.community-text h2 { margin-bottom: 20px; }
.community-text p {
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1.8;
  margin-bottom: 32px;
}

/* ── TWO WAYS ──────────────────────────────────────────────── */
.two-ways { background: var(--bg); }
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 60px;
  border: 1px solid var(--border);
}
.way-card {
  background: var(--bg-card);
  padding: 60px 50px;
  position: relative;
  overflow: hidden;
  transition: all var(--transition);
}
.way-card:hover { background: var(--bg-elevated); }
.way-card::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform 0.3s ease;
}
.way-card:hover::before { transform: scaleX(1); }
.way-icon {
  width: 56px;
  height: 56px;
  background: rgba(230, 57, 70, 0.15);
  border: 1px solid rgba(230, 57, 70, 0.3);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 28px;
  color: var(--red);
  font-size: 22px;
}
.way-card h3 { margin-bottom: 16px; color: var(--text); }
.way-card p { color: var(--text-muted); line-height: 1.8; margin-bottom: 28px; font-size: 15px; }

/* ── STUDIO EXPERIENCE ─────────────────────────────────────── */
.studio-exp {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
}
.studio-exp-bg {
  position: absolute;
  inset: 0;
  background-image: url('https://images.unsplash.com/photo-1571902943202-507ec2618e8f?w=1800&q=80');
  background-size: cover;
  background-position: center;
  filter: brightness(0.2) saturate(0.6);
}
.studio-exp-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(17,17,17,0.95) 0%, rgba(17,17,17,0.6) 60%, transparent 100%);
}
.studio-exp-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}
.studio-exp-content h2 { margin-bottom: 20px; }
.studio-exp-content p {
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1.8;
  margin-bottom: 32px;
}
.studio-exp-content .book-cta {
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  font-weight: 700;
  margin-bottom: 20px;
}

/* ── FREE TRIAL CTA ────────────────────────────────────────── */
.free-trial {
  background: var(--red);
  padding: 100px 0;
  text-align: center;
}
.free-trial h2 {
  font-size: clamp(36px, 6vw, 72px);
  margin-bottom: 32px;
  text-shadow: 0 2px 20px rgba(0,0,0,0.3);
}
.free-trial .btn-outline { border-color: #fff; }

/* ── LIFESTYLE CAROUSEL ────────────────────────────────────── */
.carousel { background: var(--bg); overflow: hidden; }
.carousel-inner {
  position: relative;
  height: 520px;
}
.carousel-track {
  display: flex;
  height: 100%;
  transition: transform 0.55s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  position: relative;
  overflow: hidden;
}
.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.75);
}
.carousel-slide-caption {
  position: absolute;
  bottom: 40px;
  left: 60px;
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 600;
  text-transform: uppercase;
  text-shadow: 0 2px 20px rgba(0,0,0,0.8);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 52px;
  height: 52px;
  background: rgba(17,17,17,0.7);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 18px;
  cursor: pointer;
  transition: all var(--transition);
  backdrop-filter: blur(4px);
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn-prev { left: 24px; }
.carousel-btn-next { right: 24px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  padding: 24px 0;
}
.carousel-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-subtle);
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active {
  width: 24px;
  border-radius: 3px;
  background: var(--red);
}

/* ── NEWSLETTER ────────────────────────────────────────────── */
.newsletter {
  background: var(--bg-card);
  border-top: 1px solid var(--border);
  padding: 80px 0;
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.newsletter-text h2 {
  font-size: clamp(24px, 4vw, 40px);
  margin-bottom: 12px;
}
.newsletter-text p {
  color: var(--text-muted);
  font-size: 15px;
}
.newsletter-form { display: flex; flex-direction: column; gap: 12px; }
.newsletter-input-wrap { position: relative; }
.newsletter-input {
  width: 100%;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 15px;
  padding: 14px 20px;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-input:focus { border-color: var(--red); }
.newsletter-input::placeholder { color: var(--text-subtle); }
.newsletter-input.error { border-color: #ff6b6b; }
.newsletter-input.success { border-color: #51cf66; }
.newsletter-error { color: #ff6b6b; font-size: 13px; display: none; }
.newsletter-error.visible { display: block; }
.newsletter-success {
  color: #51cf66;
  font-size: 14px;
  font-weight: 500;
  display: none;
}
.newsletter-success.visible { display: block; }

/* ── FOOTER ────────────────────────────────────────────────── */
footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 60px;
  margin-bottom: 60px;
}
.footer-brand .nav-logo { font-size: 20px; margin-bottom: 16px; }
.footer-brand p {
  color: var(--text-subtle);
  font-size: 14px;
  line-height: 1.7;
  margin-bottom: 24px;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 20px;
  color: var(--text);
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a {
  color: var(--text-subtle);
  font-size: 14px;
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p {
  color: var(--text-subtle);
  font-size: 13px;
}
.country-select {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 14px;
  cursor: pointer;
  color: var(--text-muted);
  font-size: 13px;
  font-family: var(--font-body);
  transition: border-color var(--transition);
  position: relative;
}
.country-select:hover { border-color: #444; }
.country-dropdown {
  display: none;
  position: absolute;
  bottom: 44px;
  right: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  min-width: 180px;
  overflow: hidden;
  z-index: 50;
}
.country-dropdown.open { display: block; }
.country-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 10px 16px;
  font-size: 14px;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--font-body);
  transition: all var(--transition);
}
.country-dropdown button:hover { background: var(--border); color: var(--text); }

/* ── PAGE HERO VARIANTS ────────────────────────────────────── */
.page-hero {
  padding: 100px 0;
  position: relative;
  overflow: hidden;
  background: var(--bg);
}
.page-hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.2) saturate(0.7);
}
.page-hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 0%, rgba(17,17,17,0.85) 100%);
}
.page-hero-content {
  position: relative;
  z-index: 2;
}
.red-line {
  display: block;
  width: 60px;
  height: 4px;
  background: var(--red);
  margin-bottom: 20px;
}

/* ── METHOD OVERVIEW ───────────────────────────────────────── */
.method-overview { background: var(--bg-card); }
.method-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.method-text h2 { margin-bottom: 20px; }
.method-text p {
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1.9;
}
.method-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.stat-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  text-align: center;
}
.stat-number {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  color: var(--red);
  line-height: 1;
  margin-bottom: 8px;
}
.stat-label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* ── WEEKLY SCHEDULE ───────────────────────────────────────── */
.schedule-section { background: var(--bg); }
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 48px;
}
.schedule-table th {
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-align: left;
  padding: 16px 24px;
  border-bottom: 2px solid var(--red);
}
.schedule-table td {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  font-size: 15px;
}
.schedule-table tr:hover td { background: var(--bg-card); }
.schedule-table td:first-child {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.schedule-badge {
  display: inline-block;
  background: rgba(230, 57, 70, 0.12);
  border: 1px solid rgba(230, 57, 70, 0.3);
  color: var(--red);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 2px;
}

/* ── FLOOR/TREADMILL TOGGLE ────────────────────────────────── */
.toggle-section { background: var(--bg-card); }
.toggle-controls {
  display: flex;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 4px;
  width: fit-content;
  margin: 0 auto 60px;
}
.toggle-btn {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 12px 40px;
  border-radius: 2px;
  transition: all 0.2s ease;
  color: var(--text-muted);
  cursor: pointer;
  border: none;
  background: none;
}
.toggle-btn.active {
  background: var(--red);
  color: #fff;
}
.toggle-content { display: none; }
.toggle-content.active { display: block; }
.toggle-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.toggle-panel-image {
  height: 420px;
  border-radius: 2px;
  overflow: hidden;
}
.toggle-panel-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.toggle-panel-text h3 {
  font-size: 32px;
  margin-bottom: 20px;
}
.toggle-panel-text p {
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1.8;
}

/* ── INSTRUCTOR GRID ───────────────────────────────────────── */
.instructors-section { background: var(--bg); }
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 60px;
}
.filter-btn {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 10px 20px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn:hover { color: var(--text); border-color: #444; }
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(230, 57, 70, 0.15);
}
.instructor-card.hidden { display: none; }
.instructor-photo {
  height: 260px;
  overflow: hidden;
  position: relative;
}
.instructor-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.8) saturate(0.8);
  transition: transform 0.4s ease;
}
.instructor-card:hover .instructor-photo img {
  transform: scale(1.04);
}
.instructor-location-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: rgba(17,17,17,0.85);
  backdrop-filter: blur(4px);
  border: 1px solid var(--border);
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--red);
  border-radius: 2px;
}
.instructor-info {
  padding: 20px;
}
.instructor-info h3 {
  font-size: 18px;
  margin-bottom: 4px;
  text-transform: uppercase;
}
.instructor-info .location {
  font-size: 12px;
  color: var(--text-subtle);
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}
.instructor-info a {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--red);
  display: flex;
  align-items: center;
  gap: 6px;
  transition: gap var(--transition);
}
.instructor-info a:hover { gap: 10px; }

/* ── FAQ ACCORDION ─────────────────────────────────────────── */
.faq-section { background: var(--bg); }
.faq-list { max-width: 820px; margin: 0 auto; display: flex; flex-direction: column; gap: 2px; }
.faq-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}
.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 28px;
  cursor: pointer;
  transition: background var(--transition);
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  color: var(--text);
}
.faq-question:hover { background: var(--bg-elevated); }
.faq-question h3 {
  font-size: 17px;
  font-family: var(--font-body);
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
}
.faq-icon {
  width: 28px;
  height: 28px;
  min-width: 28px;
  border-radius: 50%;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  color: var(--text-muted);
  transition: all var(--transition);
}
.faq-item.open .faq-icon {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 28px 24px;
  color: var(--text-muted);
  font-size: 15px;
  line-height: 1.8;
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

/* ── DIGITAL PLATFORM ──────────────────────────────────────── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 60px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 40px 32px;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--red);
  background: var(--bg-elevated);
}
.feature-number {
  font-family: var(--font-display);
  font-size: 56px;
  font-weight: 700;
  color: var(--red);
  opacity: 0.3;
  line-height: 1;
  margin-bottom: 16px;
}
.feature-card h3 {
  font-size: 20px;
  margin-bottom: 14px;
}
.feature-card p {
  color: var(--text-muted);
  font-size: 14px;
  line-height: 1.8;
}

/* ── WORKOUT TYPES GRID ────────────────────────────────────── */
.workout-types { background: var(--bg-card); }
.wtype-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 50px;
}
.wtype-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px 20px;
  text-align: center;
  transition: all var(--transition);
  cursor: pointer;
}
.wtype-card:hover { border-color: var(--red); background: var(--bg-card); }
.wtype-icon { font-size: 32px; margin-bottom: 12px; }
.wtype-card h4 {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.wtype-card p { font-size: 12px; color: var(--text-subtle); }

/* ── UNLIMITED ACCESS ──────────────────────────────────────── */
.unlimited-section { background: var(--bg); }
.unlimited-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.unlimited-image {
  position: relative;
  height: 500px;
  border-radius: 2px;
  overflow: hidden;
}
.unlimited-image img { width: 100%; height: 100%; object-fit: cover; filter: brightness(0.75); }
.unlimited-image::before {
  content: '';
  position: absolute;
  inset: 0;
  border: 2px solid rgba(230, 57, 70, 0.3);
  z-index: 1;
  border-radius: 2px;
}
.unlimited-list { list-style: none; margin-top: 28px; display: flex; flex-direction: column; gap: 16px; }
.unlimited-list li {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  color: var(--text-muted);
  font-size: 15px;
  line-height: 1.7;
}
.unlimited-list li::before {
  content: '—';
  color: var(--red);
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}

/* ── RESPONSIVENESS ────────────────────────────────────────── */
@media (max-width: 1024px) {
  .navbar { padding: 0 24px; }
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .nav-actions .nav-btn-ghost { display: none; }
  .container { padding: 0 24px; }
  .container-wide { padding: 0 24px; }
  .instructor-grid { grid-template-columns: repeat(2, 1fr); }
  .features-grid { grid-template-columns: 1fr 1fr; }
  .wtype-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 40px; }
}

@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .hero { min-height: 70vh; }
  .community-inner { grid-template-columns: 1fr; gap: 40px; }
  .community-image { height: 280px; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 40px; }
  .method-inner { grid-template-columns: 1fr; gap: 40px; }
  .toggle-panel { grid-template-columns: 1fr; gap: 40px; }
  .toggle-panel-image { height: 260px; }
  .instructor-grid { grid-template-columns: 1fr 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .wtype-grid { grid-template-columns: 1fr 1fr; }
  .unlimited-inner { grid-template-columns: 1fr; gap: 40px; }
  .unlimited-image { height: 280px; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .hero-actions { flex-direction: column; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .method-stats { grid-template-columns: 1fr; }
  .wtype-grid { grid-template-columns: 1fr 1fr; }
  .container { padding: 0 16px; }
}

/* ── ANIMATIONS ────────────────────────────────────────────── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-up { animation: fadeUp 0.6s ease-out both; }
.fade-up-d1 { animation-delay: 0.1s; }
.fade-up-d2 { animation-delay: 0.2s; }
.fade-up-d3 { animation-delay: 0.3s; }
